'use strict';
let speechProcessing=false,localSpeechStatus={transcription:false,lipSync:false};
document.body.insertAdjacentHTML('beforeend',`<dialog id="speechDialog"><div class="tool-heading"><div><div class="eyebrow">VOICE INTO ANIMATION</div><h2>Captions & lip-sync</h2></div><button id="closeSpeech">Close</button></div><p class="note">Analyze imported audio locally on this PC. Choose the narration clip and character, then review the generated captions and mouth timing.</p><label>Audio clip<select id="speechAudio"></select></label><label>Language<select id="speechLanguage"><option value="auto">Detect language</option><option value="en">English</option><option value="af">Afrikaans</option><option value="zu">Zulu</option><option value="fr">French</option><option value="es">Spanish</option><option value="de">German</option></select></label><label>Words per caption<select id="captionChunkSize"><option value="3">3 · short</option><option value="6" selected>6 · standard</option><option value="8">8 · longer</option></select></label><label>Character<select id="speechCharacter"></select></label><div class="tool-row"><button id="generateCaptions" class="primary">Generate captions</button><button id="generateLipSync">Generate mouth animation</button></div><p id="speechRuntimeStatus" class="note">Checking local speech tools…</p><div id="speechProgress" class="task-progress" role="status"></div><details open><summary>Caption appearance</summary><label>Style<select id="captionDisplay"><option value="plain">Plain</option><option value="highlight">Highlight spoken words</option></select></label><label>Position<select id="captionPosition"><option value="bottom">Bottom</option><option value="center">Center</option><option value="top">Top</option></select></label><label>Text size<input id="captionSize" type="number" min="16" max="60" value="27"></label><button id="applyCaptionStyle">Apply to project captions</button></details><details><summary>Recognized transcript</summary><textarea id="recognizedTranscript" rows="6" readonly placeholder="The recognized words will appear here."></textarea><p class="note">Edit caption text and timing in the scene inspector. The small local model may need corrections, especially with noisy recordings. Analyze up to five minutes per clip. Regenerate timing after changing footage speed.</p></details></dialog>`);
async function refreshSpeechStatus(){try{const response=await fetch('/api/status',{cache:'no-store'});if(!response.ok)throw Error();localSpeechStatus=await response.json();$('speechRuntimeStatus').textContent='Transcription: '+(localSpeechStatus.transcription?'ready':'local tools not ready')+' · Mouth analysis: '+(localSpeechStatus.lipSync?'ready':'local tools not ready');$('generateCaptions').disabled=speechProcessing||!localSpeechStatus.transcription||!tracks().length;$('generateLipSync').disabled=speechProcessing||!localSpeechStatus.lipSync||!tracks().length}catch{$('speechRuntimeStatus').textContent='Local speech service is unavailable. Run the preview server to enable speech analysis.';$('generateCaptions').disabled=true;$('generateLipSync').disabled=true}}
function populateSpeechDialog(){const audio=$('speechAudio'),characters=$('speechCharacter');audio.replaceChildren();characters.replaceChildren();for(const c of tracks()){const option=document.createElement('option');option.value=c.id;option.textContent=c.name+' · '+c.duration.toFixed(1)+' s';audio.append(option)}if(selectedAudio&&tracks().some(c=>c.id===selectedAudio))audio.value=selectedAudio;else{const narration=tracks().find(c=>c.role==='narration');if(narration)audio.value=narration.id}for(const s of project.scenes)for(const o of s.objects.filter(o=>['character','puppet'].includes(o.type))){const option=document.createElement('option');option.value=o.id;option.textContent=s.name+' · '+o.name+(o.locked?' (locked)':'');characters.append(option)}if(['character','puppet'].includes(object()?.type))characters.value=selected;const style=current().captionStyle||{mode:'plain',position:'bottom',size:27};$('captionDisplay').value=style.mode;$('captionPosition').value=style.position;$('captionSize').value=style.size;const c=tracks().find(c=>c.id===audio.value);$('recognizedTranscript').value=(c?.words||[]).map(w=>w.text).join(' ')}
$('speechTools').onclick=()=>{stop();populateSpeechDialog();refreshSpeechStatus();$('speechDialog').showModal()};$('closeSpeech').onclick=()=>$('speechDialog').close();$('speechAudio').onchange=()=>{const c=tracks().find(c=>c.id===$('speechAudio').value);$('recognizedTranscript').value=(c?.words||[]).map(w=>w.text).join(' ')};
setInterval(()=>{if($('speechDialog').open&&!speechProcessing)refreshSpeechStatus()},5000);
function sourceAudioSlice(c){const buffer=audioBuffers.get(c.id);if(!buffer)throw Error('Audio is still loading. Try again.');const duration=c.duration*(c.rate||1);if(duration>300)throw Error('Trim this clip to five minutes or less for analysis.');const start=Math.floor(c.offset*buffer.sampleRate),length=Math.min(buffer.length-start,Math.ceil(duration*buffer.sampleRate));if(length<=0)throw Error('This audio selection is empty.');const context=new OfflineAudioContext(buffer.numberOfChannels,length,buffer.sampleRate),slice=context.createBuffer(buffer.numberOfChannels,length,buffer.sampleRate);for(let ch=0;ch<buffer.numberOfChannels;ch++)slice.copyToChannel(buffer.getChannelData(ch).subarray(start,start+length),ch);return wavBlob(slice)}
function captionChunks(words,max){const chunks=[];let current=[];for(const word of words){if(current.length&&(current.length>=max||word.start-current.at(-1).end>.65)){chunks.push(current);current=[]}current.push(word);if(/[.!?]$/.test(word.text)&&current.length>=3){chunks.push(current);current=[]}}if(current.length)chunks.push(current);return chunks}
function applyRecognizedWords(c,words,max=6){const rate=c.rate||1,globalWords=words.map(w=>({start:c.start+(w.start-c.offset)/rate,end:c.start+(w.end-c.offset)/rate,text:w.text})),chunks=captionChunks(globalWords,max);let offset=0;for(const s of project.scenes){const end=offset+s.duration;s.captions=(s.captions||[]).filter(caption=>caption.end+offset<=c.start||caption.start+offset>=audioEnd(c));for(const chunk of chunks){const first=chunk[0].start,last=chunk.at(-1).end;if(last<=offset||first>=end)continue;const visible=chunk.filter(w=>w.end>offset&&w.start<end);if(!visible.length)continue;s.captions.push({start:Math.max(0,first-offset),end:Math.min(s.duration,last-offset),text:visible.map(w=>w.text).join(' '),words:visible.map(w=>({start:Math.max(0,w.start-offset),end:Math.min(s.duration,w.end-offset),text:w.text}))})}s.captions.sort((a,b)=>a.start-b.start);offset=end}}
async function analyzeSpeech(kind){if(speechProcessing||recording)return;stop();const c=tracks().find(c=>c.id===$('speechAudio').value),character=project.scenes.flatMap(s=>s.objects).find(o=>o.id===$('speechCharacter').value);if(!c)return toast('Import and select a narration clip.');if(kind==='lipsync'&&(!character||character.locked))return toast('Select an unlocked character.');const target=project;speechProcessing=true;window.editorTaskBusy=true;const message=kind==='transcribe'?'Transcribing speech locally…':'Recognizing mouth shapes locally…';$('speechProgress').textContent=message;$('studioTaskStatus').textContent=message;refreshSpeechStatus();try{const blob=sourceAudioSlice(c),response=await fetch('/api/'+kind+(kind==='transcribe'?'?language='+$('speechLanguage').value:''),{method:'POST',headers:{'Content-Type':'audio/wav'},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error||'Speech processing failed.');if(project!==target||!tracks().some(t=>t.id===c.id))throw Error('The project changed. Analyze the selected clip again.');if(kind==='transcribe'){const words=result.segments.flatMap(s=>s.words||[]).filter(w=>Number.isFinite(w.start)&&Number.isFinite(w.end)&&w.end>w.start&&typeof w.text==='string').map(w=>({...w,start:w.start+c.offset,end:w.end+c.offset}));if(!words.length)throw Error('No speech recognized. Try a clearer voice recording.');c.words=words;c.role='narration';applyRecognizedWords(c,words,+$('captionChunkSize').value);$('recognizedTranscript').value=words.map(w=>w.text).join(' ');$('speechProgress').textContent=words.length+' words recognized. Captions added; review text and timing.'}else{if(!Array.isArray(result.mouthCues))throw Error('No mouth shapes were generated.');c.mouthCues=result.mouthCues.filter(m=>Number.isFinite(m.start)&&Number.isFinite(m.end)&&m.end>=m.start&&/^[A-HX]$/.test(m.value)).map(m=>({...m,start:m.start+c.offset,end:m.end+c.offset}));c.role='narration';character.speechTrackId=c.id;character.lipSync=true;$('speechProgress').textContent=c.mouthCues.length+' mouth shapes linked to '+character.name+'. Preview and review timing.'}save();render()}catch(e){$('speechProgress').textContent=e.message}finally{speechProcessing=false;window.editorTaskBusy=false;$('studioTaskStatus').textContent='';refreshSpeechStatus()}}
$('generateCaptions').onclick=()=>analyzeSpeech('transcribe');$('generateLipSync').onclick=()=>analyzeSpeech('lipsync');$('applyCaptionStyle').onclick=()=>{const style={mode:$('captionDisplay').value,position:$('captionPosition').value,size:clamp(+$('captionSize').value||27,16,60),highlight:'#e5b75d'};for(const s of project.scenes)s.captionStyle={...style};save();render();$('speechProgress').textContent='Caption appearance updated across the project.'};
const speechValidator=valid;valid=function(p){return speechValidator(p)&&(p.audioClips||[]).every(c=>(!c.mouthCues||Array.isArray(c.mouthCues)&&c.mouthCues.length<100000&&c.mouthCues.every(m=>Number.isFinite(m.start)&&Number.isFinite(m.end)&&m.start>=0&&m.end>=m.start&&/^[A-HX]$/.test(m.value)))&&(!c.words||Array.isArray(c.words)&&c.words.length<100000&&c.words.every(w=>Number.isFinite(w.start)&&Number.isFinite(w.end)&&w.start>=0&&w.end>w.start&&typeof w.text==='string')))};
